import axios from 'axios';

const backendHost = window.location.hostname === 'localhost' ? 'localhost' : window.location.hostname;
const API_BASE = `http://${backendHost}:5000/api/user`;

export const getNearbyUsers = async (phone, radius) => {
    try {
        const response = await axios.get(`${API_BASE}/${phone}/nearby`, {
            params: { radius }
        });
        return response.data;
    } catch (error) {
        console.error("Error fetching nearby users:", error);
        throw error;
    }
};

export const updateDiscoverySettings = async (phone, radius) => {
    try {
        const response = await axios.put(`${API_BASE}/${phone}/settings/discovery`, {
            max_distance: radius
        });
        return response.data;
    } catch (error) {
        console.error("Error updating discovery settings:", error);
        throw error;
    }
};

export const likeUser = async (phone, targetPhone) => {
    try {
        const response = await axios.post(`${API_BASE}/${phone}/send-interest`, {
            target_phone: targetPhone
        });
        return response.data;
    } catch (error) {
        console.error("Error liking user:", error);
        throw error;
    }
};

export const updateLocation = async (phone, latitude, longitude) => {
    try {
        const response = await axios.post(`${API_BASE}/${phone}/location`, {
            latitude,
            longitude
        });
        return response.data;
    } catch (error) {
        console.error("Error updating location:", error);
        throw error;
    }
};
